"""A battle menu that ignores B gets one confirm on its top command.

g1190 chapter 9 2026-11-16: きりふだ/たいきゃく with no battle record held the
run 101 observations at a time (no_input_fallback loops).
"""
from docich.hanjuku_speedrun.hanjuku.flows.battle_menus import orphan_battle_menu_step
from docich.hanjuku_speedrun.hanjuku_font import TextLine
from docich.hanjuku_speedrun.hanjuku_screen import Screen


def menu():
    rows = ['きりふだ', 'たいきゃく']
    lines = [TextLine(176 + 16 * i, tuple((176 + 8 * j, ch) for j, ch in enumerate(word)))
             for i, word in enumerate(rows)]
    return Screen(lines, None, ''.join(rows), kind='battle_menu')


def test_the_orphan_menu_presses_its_top_command_once():
    mem = {}
    for _ in range(3):
        assert orphan_battle_menu_step(menu(), mem) == [{'type': 'pad', 'buttons': ['b'], 'hold_ms': 100}]
    assert orphan_battle_menu_step(menu(), mem) == [{'type': 'pad', 'buttons': ['a'], 'hold_ms': 100}]
    assert mem['_records'][-1]['decision'] == 'battle_menu_orphan_command'
    # bounded: the next observation does not press again
    assert orphan_battle_menu_step(menu(), mem) == []
